/*
GPT-2 Transformer Neural Net training loop. SYCL 2020 port of train_gpt2.cu
for Intel oneAPI DPC++ (icpx -fsycl). Single device, bf16 mixed precision
(ENABLE_BF16 default), oneMath BLAS column_major bf16->fp32 gemms, SYCL group
algorithms for reductions. Keeps llm.c's command line, printout and file formats.
*/
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdarg.h>
#include <string>
#include <string_view>
#include <sys/stat.h>
#include <sys/types.h>
#include <chrono>
// ----------- CPU utilities -----------
#include "llmc/utils.h"
#include "llmc/tokenizer.h"
#include "llmc/dataloader.h"
#include "llmc/rand.h"
#include "llmc/schedulers.h"
#include "llmc/sampler.h"
#include "llmc/logger.h"
#include "llmc/mfu.h"
#include "llmc/outlier_detector.h"
// ----------- SYCL utilities -----------
#include "llmc/sycl_common.h"
#include "llmc/sycl_utils.hpp"
// ----------- Layer implementations in SYCL -----------
#include "llmc/encoder.hpp"
#include "llmc/layernorm.hpp"
#include "llmc/matmul.hpp"
#include "llmc/attention.hpp"
#include "llmc/fused_classifier.hpp"
#include "llmc/adamw.hpp"
#include "llmc/global_norm.hpp"
// ----------- Single-device support -----------
#include "llmc/zero.hpp"

// ----------------------------------------------------------------------------
// global vars for I/O
char filename_buffer[512];

// ----------------------------------------------------------------------------
// global vars containing information about the SYCL device this process is running on
sycl::queue sycl_queue;
std::string sycl_device_name = "SYCL device";
// buffer size to use for device <-> disk io (kept for API compat; USM is host-visible)
constexpr const size_t IO_BUF_SIZE = 32 * 1024 * 1024;

// USM allocation helpers (device memory: private to the device on discrete GPUs).
// The host never touches these pointers directly; every host access goes through
// an explicit q.memcpy / q.memset ordered on the in-order queue.
inline void* sycl_malloc_device(size_t bytes) {
    if (bytes == 0) { return nullptr; }
    void* p = sycl::malloc_device(bytes, sycl_queue);
    if (!p) { printf("[SYCL ERROR] malloc_device failed for %zu bytes\n", bytes); exit(EXIT_FAILURE); }
    return p;
}
// Pinned host staging (fast H2D/D2H transfers, no device-side residency).
inline void* sycl_malloc_pinned(size_t bytes) {
    if (bytes == 0) { return nullptr; }
    void* p = sycl::malloc_host(bytes, sycl_queue);
    if (!p) { printf("[SYCL ERROR] malloc_host failed for %zu bytes\n", bytes); exit(EXIT_FAILURE); }
    return p;
}

// ----------------------------------------------------------------------------
// GPT-2 model definition

typedef struct {
    int max_seq_len; // max sequence length, e.g. 1024
    int vocab_size; // vocab size, e.g. 50257
    int padded_vocab_size; // padded to e.g. %128==0, 50304
    int num_layers; // number of layers, e.g. 12
    int num_heads; // number of heads in attention, e.g. 12
    int channels; // number of channels, e.g. 768
} GPT2Config;

// the parameters of the model
constexpr const int NUM_PARAMETER_TENSORS = 16;
typedef struct {
    floatX* wte; // (V, C)
    floatX* wpe; // (maxT, C)
    floatX* ln1w; // (L, C)
    floatX* ln1b; // (L, C)
    floatX* qkvw; // (L, 3*C, C)
    floatX* qkvb; // (L, 3*C)
    floatX* attprojw; // (L, C, C)
    floatX* attprojb; // (L, C)
    floatX* ln2w; // (L, C)
    floatX* ln2b; // (L, C)
    floatX* fcw; // (L, 4*C, C)
    floatX* fcb; // (L, 4*C)
    floatX* fcprojw; // (L, C, 4*C)
    floatX* fcprojb; // (L, C)
    floatX* lnfw; // (C)
    floatX* lnfb; // (C)
} ParameterTensors;
static_assert(sizeof(ParameterTensors) == NUM_PARAMETER_TENSORS * sizeof(void*), "Inconsistent sizes!");

#define TESTING
#include "train_gpt2.cpp"

// poor man's tensor checker
int check_tensor(float *a, float *b, int n, const char* label, float threshold=1e-0) {
    // a is the calculated tensor, b is the reference tensor
    int print_upto = 10;
    int ok = 1;
    float max_diff = 0.0f;
    float max_rel_error = 0.0f;
    float max_to_threshold = 0.f;
    float max_a = 0.0f;
    float max_b = 0.0f;
    float epsilon = 0.079;      // BF16 epsilon value
    printf("---\n");
    printf("checking tensor: %s\n", label);
    for (int i = 0; i < n; i++) {
        float t_eff = threshold + fabs(b[i]) * epsilon;
        float diff = fabsf(a[i] - b[i]);
        max_to_threshold = std::max(max_to_threshold, diff / t_eff);
        if (diff > max_diff) {
            max_diff = diff;
            float denom = fabsf(b[i]);
            max_rel_error = (denom == 0.0f) ? 0.0f : diff / denom;
            max_a = a[i];
            max_b = b[i];
        }
        if (diff > t_eff) {
            ok = 0;
        }
        // print the first few elements so we can visually assess the "proof" of the comparison
        if (i < print_upto) {
            printf(diff <= t_eff ? "OK " :  "NOT OK ");
            printf("%f %f\n", a[i], b[i]);
        }
    }
    // print the final result
    if (ok) {
        printf("TENSOR OK, max diff: %.3e, with rel error: %.3e (calculated=%10f, ref=%10f), %.2f%% of maximum error\n",
                max_diff, max_rel_error, max_a, max_b, max_to_threshold*100);
    } else {
        printf("TENSOR NOT OK, max diff: %.3e, with rel error: %.3e (calculated=%10f, ref=%10f), %.2f%% of maximum error\n",
                max_diff, max_rel_error, max_a, max_b, max_to_threshold*100);
    }
    return ok;
}

// the same tensors as in the train file, but in float, which are used as reference
typedef struct {
    float*  wte; // (Vp, C)
    float*  wpe; // (maxT, C)
    float*  ln1w; // (L, C)
    float*  ln1b; // (L, C)
    float*  qkvw; // (L, 3*C, C)
    float*  qkvb; // (L, 3*C)
    float*  attprojw; // (L, C, C)
    float*  attprojb; // (L, C)
    float*  ln2w; // (L, C)
    float*  ln2b; // (L, C)
    float*  fcw; // (L, 4*C, C)
    float*  fcb; // (L, 4*C)
    float*  fcprojw; // (L, C, 4*C)
    float*  fcprojb; // (L, C)
    float*  lnfw; // (C)
    float*  lnfb; // (C)
} FloatParameterTensors;
static_assert(sizeof(FloatParameterTensors) == NUM_PARAMETER_TENSORS * sizeof(void*), "Inconsistent sizes!");

// malloc_and_point, but in float and on CPU, because we use this data to check correctness on CPU
float* float_cpu_malloc_and_point_parameters(FloatParameterTensors* params, size_t* param_sizes) {
    // calculate the total number of parameters
    size_t num_parameters = 0;
    for (int i = 0; i < NUM_PARAMETER_TENSORS; i++) {
        num_parameters += param_sizes[i];
    }
    // everything is float so number of bytes to allocate is a simple multiplication
    float* params_memory = (float*)mallocCheck(num_parameters * sizeof(float));
    float** ptrs[] = {
        &params->wte, &params->wpe, &params->ln1w, &params->ln1b, &params->qkvw, &params->qkvb,
        &params->attprojw, &params->attprojb, &params->ln2w, &params->ln2b, &params->fcw, &params->fcb,
        &params->fcprojw, &params->fcprojb, &params->lnfw, &params->lnfb
    };
    float* params_memory_iterator = params_memory;
    for (int i = 0; i < NUM_PARAMETER_TENSORS; i++) {
        *(ptrs[i]) = params_memory_iterator;
        params_memory_iterator += param_sizes[i];
    }
    return params_memory;
}

int main(int argc, char *argv[]) {
    char nccl_init_method[256] = "mpi";  // "tcp" or "fs" or "mpi"
    int num_processes = -1;  // doesn't matter when using MPI
    int process_rank = -1;  // doesn't matter when using MPI
    int gpus_per_node = -1;  // doesn't matter when using MPI
    char server_ip[256] = "";  // doesn't matter when using MPI
    char fs_path[256] = "";  // doesn't matter when using MPI
    multi_gpu_config = multi_gpu_config_init(num_processes, process_rank, gpus_per_node, server_ip, fs_path, nccl_init_method);
    common_start(false, true);

/*
Matrix Multiplication, with help from oneMath BLAS (port of matmul.cuh).
Row-major logical layout everywhere (llm.c tensors are row-major):
  out(BT x OC) = inp(BT x C) * W^T + bias,  W is (OC x C) row-major.
Realised as oneMath column_major gemm with bf16 A/B and fp32 C output
(written to an fp32 buffer, then converted to bf16 with optional bias add):
  O_colm(OC x BT) = gemm(A=Wbuf trans, B=Inbuf nontrans),
  A is (C x OC) col-major == W row-major (OC x C), lda=C;
  B is (C x BT) col-major == In row-major (BT x C), ldb=C;
  C is (OC x BT) col-major == Out row-major (BT x OC), ldc=OC.

All oneMath calls are fire-and-forget on the in-order queue: successive
kernels/transfers are submitted in dependency order and never need a wait;
only host reads (via memcpy_d2h) block. Batched attention matmuls use a
single kernel launch over all (batch, head) pairs (own SYCL kernel, SYCL 2020
compliant, work-groups of 256 work-items with subgroup-friendly tiling).
*/
#ifndef SYCL_MATMUL_H
#define SYCL_MATMUL_H

#include <assert.h>
#include <type_traits>      // std::bool_constant
#include <oneapi/math/blas.hpp>
// llmc internal imports
#include "sycl_common.h"
#include "sycl_utils.hpp"
// GELU can be either fused or non-fused (kept non-fused here; fusion flags accepted for API compat)
#include "gelu.hpp"

// ----------------------------------------------------------------------------
// SYCL kernels

// dbias[OC] += sum over BT rows of dout (deterministic: fixed-grid ordered
// partial sums over rows per OC column into `aux` (needs 256*OC floats),
// then an ordered accumulation per column). Fire-and-forget.
template<typename OutFloat>
inline void matmul_backward_bias(floatX* dbias_out, OutFloat* dbias, const floatX* dout, int B, int T, int OC,
                                             bool use_aux, float* aux, int aux_rows, sycl::queue& q) {
    size_t N = (size_t)B * T;
    if (N == 0 || OC <= 0) { return; }
    // Deterministic path (always): fixed grid of partial sums + ordered tail.
    // `aux` must hold aux_rows*OC floats; callers pass the fp32 scratch buffer.
    const int P = (use_aux && aux_rows > 0) ? aux_rows : 256;
    float* partials = aux;
    size_t chunk = (N + (size_t)P - 1) / (size_t)P;
    q.parallel_for(sycl::range<2>((size_t)P, (size_t)OC), [=](sycl::id<2> id) {
        size_t r = id[0]; size_t oc = id[1];
        size_t b = r * chunk;
        size_t e = b + chunk;
        if (e > N) { e = N; }
        float acc = 0.0f;
        for (size_t i = b; i < e; i++) {
            acc += (float)dout[i * (size_t)OC + oc];
        }
        partials[r * (size_t)OC + oc] = acc;
    });
    q.parallel_for(sycl::range<1>((size_t)OC), [=](sycl::id<1> id) {
        size_t oc = id[0];
        float acc = (float)dbias[oc];
        for (int r = 0; r < P; r++) { acc += partials[(size_t)r * OC + oc]; }
        dbias_out[oc] = (floatX)acc;
    });
}

// dst[n] += sum over m rows of src (fp32), result rounded once to bf16 (deterministic order).
// Fire-and-forget; single kernel, ordered accumulation per column.
inline void reduce_add_sum(floatX* dst, const float* src, size_t n, size_t m, sycl::queue& q) {
    if (n == 0 || m == 0) { return; }
    q.parallel_for(sycl::range<1>(n), [=](sycl::id<1> id) {
        size_t i = id[0];
        float acc = 0.0f;
        for (size_t l = 0; l < m; l++) { acc += src[i + n * l]; }
        dst[i] = (floatX)((float)dst[i] + acc);
    });
}

// out(BT x OC) = inp(BT x C) @ W^T(OC x C) [+ bias], via oneMath bf16->fp32 gemm + convert kernel
inline void matmul_onemath(floatX* out, const floatX* weight, const floatX* inp, const floatX* bias,
                     int OC, int BT, int C, sycl::queue& q, float* tmp_fp32,
                     bool accumulate = false, floatX* pre_gelu = nullptr, bool backward_gelu = false,
                     floatX* gelu_src = nullptr) {
    NVTX_RANGE_FN();
    using namespace oneapi::math;
    // oneMath gemm writes fp32 C (no bf16 C support): use provided fp32 scratch
    oneapi::math::blas::column_major::gemm(q, transpose::trans, transpose::nontrans,
        (int64_t)OC, (int64_t)BT, (int64_t)C,
        1.0f, weight, (int64_t)C, inp, (int64_t)C,
        accumulate ? 1.0f : 0.0f, tmp_fp32, (int64_t)OC);
    size_t N = (size_t)OC * BT;
    bool has_bias = (bias != nullptr);
    bool has_gelu_fwd = (pre_gelu != nullptr && !backward_gelu);
    // epilogue kernel: convert fp32 -> bf16 (+bias, +gelu), or dgelu-gated backward epilogue
    q.parallel_for(sycl::range<1>(N), [=](sycl::id<1> id) {
        size_t i = id[0];
        size_t oc = i % (size_t)OC;
        float v = tmp_fp32[i];
        if (backward_gelu && gelu_src != nullptr) {
            // DGELU epilogue used in QKV-backward path when fusion enabled (kept for API compat;
            // our default gelu_fusion=0 never takes this path)
            float x = (float)gelu_src[(i / (size_t)OC) * (size_t)C + oc % (size_t)C];

/*
Attention (own kernels, no cuDNN), SYCL 2020 port of attention.cuh.
Batched matmuls run as a single kernel launch over all (batch, head) pairs
(see matmul.hpp). All launches are fire-and-forget on the in-order queue.
*/
#ifndef SYCL_ATTENTION_H
#define SYCL_ATTENTION_H

#include <assert.h>
// llmc internal imports
#include "sycl_common.h"
#include "sycl_utils.hpp"
#include "matmul.hpp"

// ----------------------------------------------------------------------------
// SYCL kernels

inline void permute(floatX* qo, floatX* ko, floatX* vo,
                               const floatX* inp,
                               int B, int N, int NH, int d, sycl::queue& qq) {
    sycl::queue& q = qq;
    size_t total = (size_t)B * NH * N * d;
    q.parallel_for(sycl::range<1>(total), [=](sycl::id<1> id) {
        size_t idx = id[0];
        size_t b = idx / ((size_t)NH * N * d);
        size_t rest = idx % ((size_t)NH * N * d);
        size_t nh_ = rest / ((size_t)N * d);
        rest = rest % ((size_t)N * d);
        size_t n = rest / (size_t)d;
        size_t d_ = rest % (size_t)d;
        size_t inp_idx = (b * N * 3 * NH * d) + (n * 3 * NH * d) + (nh_ * d) + d_;
        qo[idx] = inp[inp_idx];
        ko[idx] = inp[inp_idx + (size_t)NH * d];
        vo[idx] = inp[inp_idx + 2 * (size_t)NH * d];
    });
}

inline void permute_backward(floatX* dinp,
                                        const floatX* dq, const floatX* dk, const floatX* dv,
                                        int B, int N, int NH, int d, sycl::queue& qq) {
    sycl::queue& q = qq;
    size_t total = (size_t)B * NH * N * d;
    q.parallel_for(sycl::range<1>(total), [=](sycl::id<1> id) {
        size_t idx = id[0];
        size_t b = idx / ((size_t)NH * N * d);
        size_t rest = idx % ((size_t)NH * N * d);
        size_t nh_ = rest / ((size_t)N * d);
        rest = rest % ((size_t)N * d);
        size_t n = rest / (size_t)d;
        size_t d_ = rest % (size_t)d;
        size_t inp_idx = (b * N * 3 * NH * d) + (n * 3 * NH * d) + (nh_ * d) + d_;
        dinp[inp_idx] = dq[idx];
        dinp[inp_idx + (size_t)NH * d] = dk[idx];
        dinp[inp_idx + 2 * (size_t)NH * d] = dv[idx];
    });
}

inline void unpermute(floatX* inp, floatX *out, int B, int N, int NH, int d, sycl::queue& qq) {
    sycl::queue& q = qq;
    size_t total = (size_t)B * NH * N * d;
    q.parallel_for(sycl::range<1>(total), [=](sycl::id<1> id) {
        size_t idx = id[0];
        size_t b = idx / ((size_t)NH * N * d);
        size_t rest = idx % ((size_t)NH * N * d);
        size_t nh_ = rest / ((size_t)N * d);
        rest = rest % ((size_t)N * d);
        size_t n = rest / (size_t)d;
        size_t d_ = rest % (size_t)d;
        size_t other_idx = (b * NH * N * d) + (n * NH * d) + (nh_ * d) + d_;
        out[other_idx] = inp[idx];
    });
}

inline void unpermute_backward(floatX* dinp, const floatX *dout, int B, int N, int NH, int d, sycl::queue& qq) {
    sycl::queue& q = qq;
    size_t total = (size_t)B * NH * N * d;
    q.parallel_for(sycl::range<1>(total), [=](sycl::id<1> id) {
        size_t idx = id[0];
        size_t b = idx / ((size_t)NH * N * d);
        size_t rest = idx % ((size_t)NH * N * d);
        size_t nh_ = rest / ((size_t)N * d);
        rest = rest % ((size_t)N * d);
        size_t n = rest / (size_t)d;
        size_t d_ = rest % (size_t)d;
        size_t other_idx = (b * NH * N * d) + (n * NH * d) + (nh_ * d) + d_;
        dinp[idx] = (floatX)dout[other_idx];
    });
}

// inp, out shape: (NT, T, T) row-major batches, where NT = B * NH; autoregressive causal.
inline void softmax_forward(floatX* out, float inv_temperature, const floatX* inp, int NT, int T, sycl::queue& qq) {
    sycl::queue& q = qq;
    size_t rows = (size_t)NT * T;
    q.parallel_for(sycl::range<1>(rows), [=](sycl::id<1> id) {
        size_t idx = id[0];
        size_t own_pos = idx % (size_t)T;
        const floatX* x = inp + idx * (size_t)T;
        const float flt_max = 340282346638528859811704183484516925440.0f;
        float maxval = -flt_max;
