 public:
    NvtxRange(const char* s) { (void)s; }
    NvtxRange(const std::string& base_str, int number) { (void)base_str; (void)number; }
    ~NvtxRange() { }
};
#define NVTX_RANGE_FN() NvtxRange nvtx_range(__FUNCTION__)

