inline void softmax_autoregressive_backward_inplace(floatX* datt, const floatX* att,
                                                               int B, int T, int NH, float scale, sycl::queue& qq) {
    sycl::queue& q = qq;
    size_t rows = (size_t)B * NH * T;
    q.parallel_for(sycl::range<1>(rows), [=](sycl::id<1> id) {
        size_t r = id[0];
        size_t t = r % (size_t)T;
        const floatX* att_bth = att + r * (size_t)T;
        const floatX* datt_bth = datt + r * (size_t)T;
        floatX* dpreatt_bth = datt + r * (size_t)T;
        float local_sum = 0.0f;
        for (size_t t2 = 0; t2 <= t; t2++) {
            local_sum += (float)att_bth[t2] * (float)datt_bth[t2];
        }
        // copy datt row aside first (in-place op): recompute below from snapshot
        for (size_t t3 = 0; t3 < (size_t)T; t3++) {
            float d = (t3 <= t) ? (float)datt_bth[t3] : 0.0f;
            float a = (t3 <= t) ? (float)att_bth[t3] : 0.0f;
            float acc = (t3 <= t) ? a * (d - local_sum) : 0.0f;
            dpreatt_bth[t3] = (floatX)(scale * acc);
        }
    });
}

// ----------------------------------------------------------------------------
// launchers

inline void attention_forward(floatX* out, floatX* qkvr, floatX* att,
                       floatX* inp,
                       int B, int T, int C, int NH, sycl::queue& q, float* tmp_fp32) {
    NVTX_RANGE_FN();
    // Note: `inp` is not needed for backward pass, so we re-use it as a scratch buffer.
    const int HS = C / NH; // head size

    floatX *qq_, *kk, *vv;
    qq_ = qkvr + 0 * (size_t)B * T * C;
    kk = qkvr + 1 * (size_t)B * T * C;
    vv = qkvr + 2 * (size_t)B * T * C;
    permute(qq_, kk, vv, inp, B, T, NH, HS, q);

    floatX* preatt = inp; // reuse inp as scratch buffer
    // preatt(b) (T x T) = Q(b) (T x HS) * K(b)^T : m=T,n=T,k=HS, transA=false, transB=true
    matmul_batched_onemath(preatt, qq_, kk, T, T, HS, false, true,
        (size_t)T*T, (size_t)T*HS, (size_t)T*HS, B*NH, false, tmp_fp32, q);

    float scale = 1.f / sqrtf((float)HS);
    softmax_forward(att, scale, preatt, B * NH, T, q);

    floatX* vaccum = inp;
    // vaccum(b) (T x HS) = Att(b) (T x T) * V(b) (T x HS): m=T,n=HS,k=T, N,N
    matmul_batched_onemath(vaccum, att, vv, T, HS, T, false, false,
        (size_t)T*HS, (size_t)T*T, (size_t)T*HS, B*NH, false, tmp_fp32, q);

    unpermute(vaccum, out, B, T, NH, HS, q);
}

// the sequence of transformations in this compound op is:
// inp (B,T,3C) -> qkvr (B,T,3C) -> preatt (B,NH,T,T) -> att (B,NH,T,T) -> vaccum (B,T,C) -> out (B,T,C)
inline void attention_backward(floatX* dinp, floatX* dqkvr, floatX* datt, floatX* scratch,
                        const floatX* dout,
                        const floatX* qkvr, const floatX* att,
                        int B, int T, int C, int NH, sycl::queue& q, float* tmp_fp32) {
    NVTX_RANGE_FN();
    (void)scratch;
    const int HS = C / NH; // head size

    const floatX *qq_, *kk, *vv;
    qq_ = qkvr + 0 * (size_t)B * T * C;
    kk = qkvr + 1 * (size_t)B * T * C;
    vv = qkvr + 2 * (size_t)B * T * C;
    floatX *dq, *dk, *dv;
    dq = dqkvr + 0 * (size_t)B * T * C;
    dk = dqkvr + 1 * (size_t)B * T * C;
    dv = dqkvr + 2 * (size_t)B * T * C;

    // backward through the unpermute operation
    unpermute_backward(dqkvr /*reuse as scratch*/, dout, B, T, NH, HS, q);
    floatX* scratch_b = dqkvr; // (B,NH,T,HS) == (B,T,C)
    // backward into datt: datt(b) (T x T) = scratch(b) (T x HS) * V(b)^T : m=T,n=T,k=HS, N,T
    matmul_batched_onemath(datt, scratch_b, vv, T, T, HS, false, true,
        (size_t)T*T, (size_t)T*HS, (size_t)T*HS, B*NH, false, tmp_fp32, q);
    // backward into dv: dv(b) (T x HS) = Att(b)^T * scratch(b): m=T,n=HS,k=T with A transposed:
    // dv = Att^T @ scratch => m=T,n=HS,k=T, transA=true, transB=false
    matmul_batched_onemath(dv, att, scratch_b, T, HS, T, true, false,
        (size_t)T*HS, (size_t)T*T, (size_t)T*HS, B*NH, false, tmp_fp32, q);
    const float scale = 1.0f / sqrtf((float)HS);
    softmax_autoregressive_backward_inplace(datt, att, B, T, NH, scale, q);
    const floatX* dpreatt = datt;
    // backward into q: dq(b) (T x HS) = dpreatt(b) * K(b): m=T,n=HS,k=T, N,N
    matmul_batched_onemath(dq, dpreatt, kk, T, HS, T, false, false,
        (size_t)T*HS, (size_t)T*T, (size_t)T*HS, B*NH, false, tmp_fp32, q);
    // backward into k: dk(b) (T x HS) = dpreatt(b)^T * Q(b): m=T,n=HS,k=T, T,N
    matmul_batched_onemath(dk, dpreatt, qq_, T, HS, T, true, false,
        (size_t)T*HS, (size_t)T*T, (size_t)T*HS, B*NH, false, tmp_fp32, q);
    // backward into inp
    permute_backward(dinp, dq, dk, dv, B, T, NH, HS, q);
}

#endif

/*
Fused Classifier:
- Forwards the Cross Entropy Loss
- Never materializes the full normalized logits, only at the target label
- (fusion) Also kicks off the backward pass, because everything is already loaded
SYCL 2020 port of fused_classifier.cuh.
Fire-and-forget launch on the in-order queue (no per-kernel wait).
*/
#ifndef SYCL_FUSED_CLASSIFIER_H
#define SYCL_FUSED_CLASSIFIER_H

// llmc internal imports
#include "sycl_common.h"
#include "sycl_utils.hpp"

// ----------------------------------------------------------------------------
// SYCL kernels

struct SoftmaxParams {
    float Scale;
    float Offset;
};

// Compute per-row softmax normalisation constants with online softmax.
// Deterministic: sequential accumulation over the row in index order.
inline SoftmaxParams prepare_softmax_row(size_t idx, const floatX* inp, int V, int P) {
    const floatX* x = inp + idx * (size_t)P;
    float thread_maxval = -INFINITY;
    float thread_sumval = 0.0f;
    for (int i = 0; i < V; i++) {
        float v = (float)x[i];
        float old_maxval = thread_maxval;
        thread_maxval = fmaxf(thread_maxval, v);
        thread_sumval *= sycl::exp(old_maxval - thread_maxval);
        thread_sumval += sycl::exp(v - thread_maxval);
    }
    return SoftmaxParams{1.f / thread_sumval, thread_maxval};
}

// will _update_ logits to logit gradients
template <bool WriteDLogits = true>
inline void fused_classifier_kernel(floatX* logits, float* losses,
                                const float dloss, const int* targets,
                                int B, int T, int V, int P, std::bool_constant<WriteDLogits>, sycl::queue& q) {
    size_t N = (size_t)B * T;
    // Reverse row order, like the CUDA kernel (cache behaviour only; results identical).
    q.parallel_for(sycl::range<1>(N), [=](sycl::id<1> id) {
        size_t fwd = id[0];
        size_t idx = N - 1 - fwd;
        int ix = targets[idx];
        SoftmaxParams sp = prepare_softmax_row(idx, logits, V, P);
        {
            float prob = sycl::exp((float)logits[idx * (size_t)P + ix] - sp.Offset) * sp.Scale;
            losses[idx] -= sycl::log(prob);
        }
        const floatX* logits_vec = logits + idx * (size_t)P;
        floatX* dlogits_vec = logits + idx * (size_t)P;
        int vec = (int)x128::size;
        int nfull = V / vec;
        for (int i = 0; i < nfull; i++) {
            for (int k = 0; k < vec; ++k) {
                int element = i * vec + k;
                float prob = sycl::exp((float)logits_vec[element] - sp.Offset) * sp.Scale;
                float indicator = (element == ix) ? 1.0f : 0.0f;
                if (WriteDLogits) {
                    dlogits_vec[element] = (floatX)((prob - indicator) * dloss);
                }
            }
        }
        int unaligned_start = V & ~(vec - 1);
        for (int i = unaligned_start; i < V; i++) {
            float prob = sycl::exp((float)logits_vec[i] - sp.Offset) * sp.Scale;
            float indicator = (i == ix) ? 1.0f : 0.0f;
            float dlogit = (prob - indicator) * dloss;
            if (WriteDLogits) {
                dlogits_vec[i] = (floatX)dlogit;
            }
        }
    });
}

// ----------------------------------------------------------------------------
// kernel launchers

// replaces logits with logit gradients
template <typename Type, bool WriteDLogits>
inline void fused_classifier(Type* logits, float* losses,
                      const float dloss, const int* targets,
                      int B, int T, int V, int P, std::bool_constant<WriteDLogits> write_dlogits, sycl::queue& q) {
    NVTX_RANGE_FN();
    fused_classifier_kernel(logits, losses, dloss, targets, B, T, V, P, write_dlogits, q);
}

#endif

/*
Global norm, used in gradient clipping. SYCL port of global_norm.cuh.
Deterministic: fixed-grid ordered partial sums per slice (in device memory),
then an ordered accumulation per slice. `tmp` needs >= num_slices*256 floats
of device scratch. Fire-and-forget on the in-order queue.
*/
#ifndef SYCL_GLOBAL_NORM_H
#define SYCL_GLOBAL_NORM_H

#include <assert.h>
#include <stddef.h>
// llmc internal imports
#include "sycl_common.h"
#include "sycl_utils.hpp"

// ----------------------------------------------------------------------------
// launcher

// Helper function determines the maximum number of block sums (kept for API compat)
inline int get_max_num_block_sums(int* num_slices_all, int numel) {
    // SYCL port: single partial sum per call; return total slices as the bound.
    int max_num_block_sums = 0;
    for (int i = 0; i < numel; i++) {
        max_num_block_sums = std::max(max_num_block_sums, num_slices_all[i]);
    }
    return std::max(max_num_block_sums, 1);
}

// out[0..slices) accumulates sum of squares (each slice covers count elements
// at values + s*stride). Deterministic ordered accumulation.
template<typename T>
inline void global_norm_squared(float* out, const T* values, size_t count, ptrdiff_t stride, int num_slices, int max_num_block_sums, bool reset, sycl::queue& q, float* tmp) {
    (void)max_num_block_sums;
    constexpr int P = 256;
    if (num_slices <= 0) { return; }
    if (reset) {
        q.parallel_for(sycl::range<1>((size_t)num_slices), [=](sycl::id<1> id) {
            out[id[0]] = 0.0f;
        });
    }
    if (count == 0) { return; }
    int p = (count < (size_t)P) ? (int)count : P;
    size_t chunk = (count + (size_t)p - 1) / (size_t)p;
    float* partials = tmp; // num_slices * p floats of device scratch
    q.parallel_for(sycl::range<2>((size_t)num_slices, (size_t)p), [=](sycl::id<2> id) {
        size_t s = id[0];
        size_t j = id[1];
        const T* v = values + (ptrdiff_t)s * stride;
        size_t b = j * chunk;
        size_t e = b + chunk;
        if (e > count) { e = count; }
        float acc = 0.0f;
        for (size_t i = b; i < e; i++) {
            float x = (float)v[i];
            acc += x * x;
        }
        partials[s * (size_t)p + j] = acc;
    });
    q.parallel_for(sycl::range<1>((size_t)num_slices), [=](sycl::id<1> id) {
        size_t s = id[0];
        double acc = (double)out[s];
        for (int j = 0; j < p; j++) { acc += (double)partials[s * (size_t)p + j]; }
        out[s] = (float)acc;
    });
}

#endif

