#include <sycl/sycl.hpp>
#include <oneapi/math/blas.hpp>
#include <cstdio>
#include <vector>
#include <cmath>
#include <random>
using bf16 = sycl::ext::oneapi::bfloat16;
int main() {
    sycl::queue q{sycl::cpu_selector_v};
    using namespace oneapi::math;
    std::mt19937 rng(7);
    std::normal_distribution<float> d(0,0.5f);
    auto trial = [&](const char* name, int m,int n,int k,bool tA,bool tB,bool accum){
        int ra = tA?k:m, ca = tA?m:k;
        int rb = tB?n:k, cb = tB?k:n;
        std::vector<float> Af(ra*ca), Bf(rb*cb), Cf(m*n);
        for(auto&x:Af)x=d(rng); for(auto&x:Bf)x=d(rng); for(auto&x:Cf)x=d(rng)*0.1f;
        // reference with EXPLICIT bf16 output rounding (what any bf16-out GEMM should produce up to summation order)
        std::vector<float> ref(m*n);
        for(int i=0;i<m;i++)for(int j=0;j<n;j++){float s=accum?Cf[i*n+j]:0;for(int l=0;l<k;l++){
            float a=(float)bf16(tA?Af[l*m+i]:Af[i*k+l]);
            float b=(float)bf16(tB?Bf[j*k+l]:Bf[l*n+j]);
            s+=a*b;}ref[i*n+j]=(float)bf16(s);}
        std::vector<bf16> A(ra*ca),B(rb*cb),C(m*n);
        for(int i=0;i<ra*ca;i++)A[i]=bf16(Af[i]);
        for(int i=0;i<rb*cb;i++)B[i]=bf16(Bf[i]);
        for(int i=0;i<m*n;i++)C[i]=bf16(Cf[i]);
        bf16 *dA=(bf16*)sycl::malloc_device(ra*ca*sizeof(bf16),q);
        bf16 *dB=(bf16*)sycl::malloc_device(rb*cb*sizeof(bf16),q);
        float *dF=(float*)sycl::malloc_device(m*n*sizeof(float),q);
        q.memcpy(dA,A.data(),ra*ca*sizeof(bf16)).wait();
        q.memcpy(dB,B.data(),rb*cb*sizeof(bf16)).wait();
        int64_t ldu = tB ? (int64_t)k : (int64_t)n;
        int64_t ldv = tA ? (int64_t)m : (int64_t)k;
        blas::column_major::gemm(q, tB?transpose::trans:transpose::nontrans,tA?transpose::trans:transpose::nontrans,
          (int64_t)n,(int64_t)m,(int64_t)k, 1.0f, dB,ldu, dA,ldv, 0.0f, dF,(int64_t)n).wait();
